actions.script:
const share = Array.from(ec.service.sync().name('org.moqui.maps.LocationServices.find#MyShares').call()?.shareList || [])
    .find((row) => row.shareId === String(shareId ?? ''))
if (!share) ec.message.addError(ec.l10n.localize('Location share not found'))
else {
    const now = ec.user.timestampMillis(ec.user.nowTimestamp)
    // location@max-share-hours as LocationShares.js setting() reads it: a whole number, else 24
    const given = String(ec.factory.getConfValue('location@max-share-hours') ?? '').trim()
    const hours = given !== '' && Number.isInteger(Number(given)) && Number(given) >= 0 ? Number(given) : 24
    const current = Number(share.thruDate) || now
    const thru = Math.min(Math.max(current, now) + 3600000, now + hours * 3600000)
    // a share already at the longest it may be is said so, not extended by nothing
    if (thru <= current + 60000) ec.message.addMessage(ec.l10n.localize('This share already lasts as long as it may') + ' ('
        + ec.l10n.format(new Date(current), 'EEE HH:mm') + ')', 'warning')
    else {
        ec.service.sync().name('org.moqui.maps.LocationServices.update#Share').parameters({shareId: share.shareId, thruDate: new Date(thru)})
            .requireNewTransaction(true).call()
        if (!ec.message.hasError()) ec.message.addMessage(ec.l10n.localize('Shared until') + ' ' + ec.l10n.format(new Date(thru), 'EEE HH:mm'), 'success')
    }
}

const L = (text) => ec.l10n.localize(text)
let shares = []
// a read that failed (thrown, or an error it added) is said as such, never as "nobody"
readFailed = false
ec.message.pushErrors()
try {
    shares = Array.from(ec.service.sync().name('org.moqui.maps.LocationServices.find#MyShares').call()?.shareList || [])
    if (ec.message.hasError()) { ec.logger.warn('My location shares: not read: ' + ec.message.getErrorsString()); readFailed = true; shares = [] }
} catch (err) {
    ec.logger.warn('My location shares: not read: ' + (err?.message ?? err))
    readFailed = true
} finally { ec.message.clearErrors(); ec.message.popErrors() }
const now = ec.user.timestampMillis(ec.user.nowTimestamp)
const ageText = (seconds) => seconds == null ? L('No position yet') : seconds < 60 ? L('just now') : seconds < 3600
    ? Math.floor(seconds / 60) + ' ' + L('min ago') : Math.floor(seconds / 3600) + ' ' + L('h ago')
shareList = shares.filter((share) => share.active).map((share) => ({shareId: share.shareId, label: share.label || '',
    // the opt-in is offered for a share with an XMPP contact (plans/Location-Sharing.md §3.6)
    hasXmpp: Array.from(share.audienceList || []).some((row) => !row.revoked && row.audienceTypeEnumId === 'LsaXmpp'),
    takeXmpp: share.takeXmppLocation === true, takeXmppNext: share.takeXmppLocation === true ? 'false' : 'true',
    whoText: Array.from(share.audienceList || []).filter((row) => !row.revoked)
        .map((row) => row.hasLink ? L('a guest link') : row.userName || row.groupName || row.jid || '').filter(Boolean).join(', '),
    untilText: share.thruDate ? ec.l10n.format(new Date(Number(share.thruDate)), 'EEE HH:mm') : '',
    // the newest of the page's or phone's and the XMPP app's, with where it came from (plans/Location-Sharing.md §3.6)
    ageText: (share.lastSource === 'xmpp' ? ageText(share.xmppAgeSeconds) + ' · ' + L('from your XMPP app')
        : ageText(share.latest ? share.latest.ageSeconds : null) + (share.lastSource ? ' · ' + L('from this page or phone') : ''))
        + (share.approximate ? ' · ' + L('approximate, about 1 km') : '')}))
// Open in Maps: only for a user whose own grants open the Maps app (Maps.xml carries its grant, as LocalMap asks)
mapsOpen = !!ec.user.userId && !!ec.artifactExecution.isPermittedOwn('component://tools/screen/Maps.xml', 'AT_XML_SCREEN', 'view')
